set -euo pipefail
cd /home/ubuntu/apps/travel-planner
echo  | base64 -d > docs/ROUTING_STORE_CONTRACT.md
echo  | base64 -d > docs/ROUTING_EVALUATION_2026-10-12.md
echo  | base64 -d > docs/PROJECT_MEMORY.md
echo  | base64 -d > docs/PROJECT_STATUS_AND_ARCHITECTURE.md
echo  | base64 -d > rag/README.md
.venv/bin/python - <<'PY'
import ast,hashlib,json
from pathlib import Path
paths=['rag/service/intent_classifier.py','rag/service/store_contract.py','rag/service/semantic_router.py','rag/service/routing_prototypes.json','rag/service/ticket_service.py','rag/service/retrieval_server.py','rag/service/answer_service.py','rag/retrieval/search_chunks.py']
versions={p:hashlib.sha256(Path(p).read_bytes()).hexdigest() for p in paths}
answer=ast.parse(Path('rag/service/answer_service.py').read_text())
prompt=next(ast.literal_eval(n.value) for n in answer.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='PROMPT' for t in n.targets))
versions['answer_prompt_sha256']=hashlib.sha256(prompt.encode()).hexdigest()
record_path=Path('rag/eval/reports/routing_v2_live_regression.json')
record=json.loads(record_path.read_text())
record['versions']=versions
record['routing_config']={'RAG_SEMANTIC_ROUTING_ENABLED':1,'threshold':0.60,'margin':0.06,'model':'BAAI/bge-m3','classifier_llm_calls':0}
record_path.write_text(json.dumps(record,ensure_ascii=False,indent=2))
print('Versioned live routing report saved; answer prompt unchanged')
PY
